import { useState, useEffect, useRef } from 'react'
import { Row, Col } from 'antd'
import { get, size } from 'lodash'

import StepWrapper from '../components/Step'
import Step3Wrapper from '../index'
import EndorsementPage from './pages/endorsementPage'
import { EndorsementProvider } from './context'
import { GenericEndorsementContextProvider } from './context/genericEndorsementContext'

export default function EndorsementUIConfig (props) {
  const [newStep, setNewStep] = useState({
    provider: false,
    endorsement: true
  })
  const [productCode, setProductCode] = useState('')
  const [packageCode, setPackageCode] = useState('')
  const that = useRef({
    isCall: false
  })

  useEffect(() => {
    if (!that.current.isCall) {
      const { location } = props
      if (size(get(location, 'state', {})) > 0) {
        const formData = get(location, 'state.formData', {})
        const step1Data = get(location, 'state.formData.step1Data', '')
        setProductCode(get(step1Data, 'code'))
        setPackageCode(get(formData, 'packageData.code'))
        const providerSection = get(formData, 'packageData.document_generation_source') === 'provider' || get(formData, 'packageData.policy_number_source') === 'provider'
        setNewStep({
          ...newStep,
          provider: providerSection
        })
      }
      that.current.isCall = true
    }
  }, [newStep, props])
  return (
    <Step3Wrapper>
      <StepWrapper
        current={3}
        newSteps={newStep}
      >
        <Row type='flex' justify='center'>
          <Col span={22}>
            <GenericEndorsementContextProvider>
              <EndorsementProvider>
                {
                  (productCode && packageCode) &&
                    <EndorsementPage
                      props={props}
                      view='add'
                      productCodeData={productCode}
                      packageCode={packageCode}
                    />
                }
              </EndorsementProvider>
            </GenericEndorsementContextProvider>
          </Col>
        </Row>
      </StepWrapper>
    </Step3Wrapper>
  )
}
